/**
 * Prerender public SEO routes after vite build.
 * Routes are read from dist/learn-routes.json (generated by generate-routes.mjs).
 * Skipped on Vercel (VERCEL=1) — prerendered files are uploaded from local dist/.
 */

if (process.env.VERCEL) {
  console.log('ℹ  Skipping prerender on Vercel (prebuilt dist/ is used instead).');
  process.exit(0);
}

import puppeteer from 'puppeteer'
import { createServer } from 'http'
import { readFileSync, writeFileSync, mkdirSync, existsSync, statSync } from 'fs'
import { resolve, extname, dirname } from 'path'
import { fileURLToPath } from 'url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const DIST = resolve(__dirname, '../dist')

// MIME types for static file serving
const MIME = {
  '.html': 'text/html',
  '.js':   'application/javascript',
  '.css':  'text/css',
  '.json': 'application/json',
  '.png':  'image/png',
  '.svg':  'image/svg+xml',
  '.ico':  'image/x-icon',
  '.woff2':'font/woff2',
  '.woff': 'font/woff',
  '.ttf':  'font/ttf',
}

// Routes from the manifest — generated by generate-routes.mjs.
// '/' is always last in the manifest (overwrites dist/index.html used as SPA fallback).
const manifest = JSON.parse(readFileSync(resolve(DIST, 'learn-routes.json'), 'utf8'))
const ROUTES = manifest.prerender

function startServer(port) {
  return new Promise((res) => {
    const server = createServer((req, reply) => {
      let filePath = resolve(DIST, req.url.split('?')[0].slice(1) || 'index.html')

      // SPA fallback: serve index.html for unknown or directory paths.
      // Must check isFile() to avoid treating prerendered subdirs as static files.
      const isFile = existsSync(filePath) && statSync(filePath).isFile();
      if (!isFile || filePath === DIST) {
        filePath = resolve(DIST, 'index.html')
      }

      const ext = extname(filePath)
      const mime = MIME[ext] || 'application/octet-stream'
      try {
        const data = readFileSync(filePath)
        reply.writeHead(200, { 'Content-Type': mime })
        reply.end(data)
      } catch {
        reply.writeHead(404)
        reply.end('Not found')
      }
    })
    server.listen(port, '127.0.0.1', () => res(server))
  })
}

async function prerender() {
  const PORT = 7788
  const server = await startServer(PORT)
  console.log(`Static server listening on http://127.0.0.1:${PORT}`)

  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  })

  try {
    for (const route of ROUTES) {
      const url = `http://127.0.0.1:${PORT}${route}`
      const page = await browser.newPage()

      // Block images and fonts to speed up rendering; allow scripts + styles
      await page.setRequestInterception(true)
      page.on('request', (req) => {
        const type = req.resourceType()
        if (['document', 'script', 'stylesheet'].includes(type)) {
          req.continue()
        } else {
          req.abort()
        }
      })

      await page.goto(url, { waitUntil: 'networkidle0', timeout: 30000 })

      // Wait for the landing page H1 to appear
      await page.waitForSelector('h1', { timeout: 15000 }).catch(() => {
        console.warn(`⚠️  h1 not found for ${route} — saving anyway`)
      })

      const html = await page.content()

      const outPath =
        route === '/'
          ? resolve(DIST, 'index.html')
          : resolve(DIST, route.slice(1), 'index.html')

      if (route !== '/') {
        mkdirSync(dirname(outPath), { recursive: true })
      }

      writeFileSync(outPath, html, 'utf8')
      console.log(`✅  Prerendered ${route} → ${outPath.replace(DIST, 'dist')}`)

      // Verify key SEO signals are present
      const checks = [
        ['<title>', html.includes('<title>')],
        ['<h1', html.includes('<h1')],
        ['canonical', html.includes('rel="canonical"')],
        ['description', html.includes('name="description"')],
      ]
      for (const [label, pass] of checks) {
        console.log(`   ${pass ? '✓' : '✗'} ${label}`)
      }

      await page.close()
    }
  } finally {
    await browser.close()
    server.close()
  }
}

prerender().catch((err) => {
  console.error('Prerender failed:', err)
  process.exit(1)
})
